def game_score(points: str) -> str:
    a_points = 0
    b_points = 0

    for point in points:
        # Check if game is already won
        if a_points >= 4 and a_points > b_points:
            return "Game A"
        if b_points >= 4 and b_points > a_points:
            return "Game B"

        # Award the point
        if point == 'A':
            a_points += 1
        else:
            b_points += 1

    # Check if game is won after processing all points
    if a_points >= 4 and a_points > b_points:
        return "Game A"
    if b_points >= 4 and b_points > a_points:
        return "Game B"

    # Convert points to tennis score
    score_map = {0: '0', 1: '15', 2: '30', 3: '40'}

    # Handle 40-40 (deuce) case
    if a_points >= 3 and b_points >= 3:
        return "40-40"

    # Normal scoring
    a_score = score_map[min(a_points, 3)]
    b_score = score_map[min(b_points, 3)]

    return f"{a_score}-{b_score}"
